// Some portions generated by Codex
import assert from "node:assert/strict";
import test from "node:test";
import { collectionContinuationQuery, COLLECTION_CONTINUATION_LIMIT } from "../../../main/frontend/graph-explorer/collection-query.ts";
import { sparqlNodeId } from "../../../main/frontend/graph-explorer/rdf-terms.ts";
import { EXCLUSION_BUDGET } from "../../../main/frontend/graph-explorer/rdf-vocabulary.ts";

const RDF = "http://www.w3.org/1999/02/22-rdf-syntax-ns#";
const edge = (source, predicate, target, id = `${source}|${predicate}|${target}`) =>
  ({id, source, predicate, target, label: predicate});
const loadedGraph = (edges) => ({nodes: [], edges, revision: 0});

test("continuation keeps its anchor and path together within the selected graph and requests a bounded answer", () => {
  const query = collectionContinuationQuery("urn:tail", "urn:graph");
  assert.match(query, /GRAPH <urn:graph> \{/);
  assert.match(query, /VALUES \?start \{ <urn:tail> \}/);
  assert.match(query, /\?start <http:\/\/www.w3.org\/1999\/02\/22-rdf-syntax-ns#rest>\* \?source/);
  assert.match(query, /\?source \?predicate \?target/);
  assert.ok(query.endsWith(`LIMIT ${COLLECTION_CONTINUATION_LIMIT + 1}`));
});

test("continuation accepts a certified repository blank reference and rejects document-local blank IDs", () => {
  const certified = sparqlNodeId({type:"bnode",value:"pending-tail","rdf4j:reference":true});
  assert.match(collectionContinuationQuery(certified,"default"), /<_:pending-tail>/);
  const document = sparqlNodeId({type:"bnode",value:"pending-tail"});
  assert.throws(() => collectionContinuationQuery(document,"default"));
  assert.throws(() => collectionContinuationQuery('urn:x> } UNION { ?s ?p ?o } #',"default"));
});

test("frontier first/rest facts receive priority over metadata without sorting an unbounded path result", () => {
  const query = collectionContinuationQuery("urn:tail", "default");
  assert.match(query, /VALUES \?predicate \{ <http:\/\/www.w3.org\/1999\/02\/22-rdf-syntax-ns#first> <http:\/\/www.w3.org\/1999\/02\/22-rdf-syntax-ns#rest> \}/);
  assert.match(query, /ORDER BY \?__collectionPriority/);
  assert.equal((query.match(new RegExp(`LIMIT ${COLLECTION_CONTINUATION_LIMIT + 1}\\b`, "g")) ?? []).length, 3,
    "both branch answers must be bounded before the outer priority sort");
  assert.match(query, /\?source \?predicate \?target/, "ordinary outgoing metadata remains loadable");
});

test("continuation skips loaded certified and literal facts while preserving safe query tokens", () => {
  const tail = sparqlNodeId({type:"bnode",value:"tail","rdf4j:reference":true});
  const member = sparqlNodeId({type:"literal",value:'already "loaded"\nvalue'});
  const temporary = sparqlNodeId({type:"bnode",value:"document-only","rdf4j:scope":"answer"});
  const graph = loadedGraph([
    edge(tail, `${RDF}first`, member),
    edge(tail, "urn:metadata", "urn:loaded-value"),
    edge(tail, "urn:temporary", temporary),
    edge("urn:unrelated", "urn:metadata", "urn:unrelated-value"),
  ]);
  const query = collectionContinuationQuery(tail, "urn:graph", graph);
  assert.match(query, /MINUS \{ VALUES \(\?source \?predicate \?target\)/);
  assert.ok(query.includes(`(<_:tail> <${RDF}first> "already \\"loaded\\"\\nvalue")`));
  assert.ok(query.includes("(<_:tail> <urn:metadata> <urn:loaded-value>)"));
  assert.ok(!query.includes("document-only"), "document-local blank labels are never reusable query operands");
  assert.ok(!query.includes("unrelated-value"), "unrelated resources do not spend the list exclusion budget");
});

test("loaded-fact exclusions remain bounded and reserve budget for the current frontier", () => {
  const edges = [];
  for (let i = 0; i < 10_000; i++) edges.push(edge(`urn:old:${i}`, `${RDF}first`, `urn:member:${i}`));
  edges.push(edge("urn:tail", `${RDF}first`, "urn:frontier-member"));
  const query = collectionContinuationQuery("urn:tail", "all", loadedGraph(edges));
  assert.ok(query.includes("(<urn:tail>"), "current frontier exclusions take precedence over older cells");
  assert.ok(query.length <= EXCLUSION_BUDGET, "the query respects the existing safe exclusion budget");
  assert.ok(!query.includes("urn:old:9999"), "the query does not serialize every loaded cell");
});
